#include "WCP2dToy/TimeKeeper.h"

#include <sstream>
#include <iostream>		// debugging

using namespace std;
using namespace WCP;

/**
 * @brief Constructor for TimeKeeper class
 * @param msg Message associated with the event
 * @param starting_time Starting time of the event
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.5.
*/ 
TimeKeeper::TimeKeeper(const std::string& msg, ptime starting_time)
{
    //cerr << "TimeKeeper starting with \"" << msg << "\"" << endl;
    m_events.push_back(event(starting_time, msg));
}

TimeKeeper::~TimeKeeper()
{
}

/**
 * @brief Processes an event with the given message and current time
 * @param msg Message associated with the event
 * @param now Current time of the event
 * @return Result of emitting the event
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.5.
*/ 
std::string TimeKeeper::operator()(std::string msg, ptime now)
{
    //cerr << "TimeKeeper: accepting message: " << msg << endl;
    m_events.push_back(event(now, msg));
    return emit(-1);
}

/**
 * @brief Returns the start time of the TimeKeeper object
 * @return The start time as a boostposix_timeptime object
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.5.
*/ 
boost::posix_time::ptime TimeKeeper::start_time() const
{
    return (*this)[0].first;
}
/**
 * @brief Returns the last time stored in the TimeKeeper object
 * @return The most recent time
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.5.
*/ 
boost::posix_time::ptime TimeKeeper::last_time() const
{
    return (*this)[-1].first;
}
/**
 * @brief Calculates the time difference between the last two events.
 * @return The duration between the last two events.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.5.
*/ 
TimeKeeper::deltat TimeKeeper::last_duration() const
{
    return (*this)[-1].first - (*this)[-2].first;
}

/**
 * @brief Calculates the time duration since the start time
 * @param now Current time
 * @return Time duration since the start time
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.5.
*/ 
boost::posix_time::time_duration TimeKeeper::since(ptime now) const
{
    return now - start_time();
}

/**
 * Returns the event at the specified index, handling negative indices by wrapping around to the end of the list.
 *
 * @param ind the index of the event to retrieve
 * @return the event at the specified index
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.5.
*/ 
TimeKeeper::event TimeKeeper::operator[](int ind) const
{
    while (ind < 0) { ind += m_events.size();}

    return m_events[ind];
}

/**
 * @brief Generates a summary string for all events.
 * 
 * This function iterates over all stored events and appends their string representations to a single output string.
 * 
 * @return A string containing summaries of all events.* This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.5.
*/ 
std::string TimeKeeper::summary() const
{
    stringstream ss;
    for (int ind=0; ind<m_events.size(); ++ind) {
	ss << this->emit(ind) << "\n";
    }
    return ss.str();
}

/**
 * @brief Emits a string representing the timing information of an event.
 * 
 * This function generates a string that includes the total milliseconds 
 * elapsed since the start of the events and the milliseconds elapsed 
 * between the current and previous events.
 * 
 * @param ind The index of the event for which the timing information is generated.
 * @return A string containing the timing information of the event.
 * This comment was generated by meta-llama/Llama-3.3-70B-Instruct:None at temperature 0.5.
*/ 
std::string TimeKeeper::emit(int ind) const
{
    while (ind < 0) { ind += m_events.size();}
    //cerr << "emit " << ind << endl;
    int prev_ind = ind-1;
    if (prev_ind<0) prev_ind=0;
    const event& prev = (*this)[prev_ind];
    const event& evt = (*this)[ind];

    deltat from_start = since(evt.first);
    deltat from_last = evt.first - prev.first;

    stringstream ss;
    ss << "TICK: " << from_start.total_milliseconds() << " ms "
       << "(this: " << from_last.total_milliseconds() << " ms) "
       << evt.second;
    return ss.str();
}
